<?php
namespace App\Http\Controllers\Api; use App\Http\Requests\Api\PayrollRequest; use App\Models\Payroll; use App\Traits\ApiResponseTrait; use Illuminate\Http\Request;
class PayrollController {use ApiResponseTrait; public function index(Request $r){return $this->success(Payroll::with('employee')->when($r->employee_id,fn($q,$v)=>$q->where('employee_id',$v))->when($r->period_year,fn($q,$v)=>$q->where('period_year',$v))->latest()->paginate(15));} public function store(PayrollRequest $r){$d=$r->validated();$d['base_salary']=$d['base_salary']??optional(\App\Models\Employee::find($d['employee_id']))->base_salary??0;$d['gross_pay']=$d['base_salary']+($d['overtime_pay']??0)+($d['bonuses']??0)+($d['benefits_in_kind']??0);$d['social_security_employee']=round($d['gross_pay']*.01,2);$d['taxes']=round($d['gross_pay']*.05,2);$d['net_pay']=$d['gross_pay']-$d['social_security_employee']-$d['taxes'];return $this->success(Payroll::create($d),'Payroll generated',201);} public function show(Payroll $payroll){return $this->success($payroll->load('employee'));} public function validatePayroll(Payroll $p){$p->update(['status'=>'validated']);return $this->success($p->fresh());} public function pay(Request $r,Payroll $p){$p->update(['status'=>'paid','payment_date'=>$r->input('payment_date',now()),'payment_reference'=>$r->input('payment_reference')]);return $this->success($p->fresh());} public function employee(int $employee){return $this->success(Payroll::where('employee_id',$employee)->latest()->paginate(15));}}
